// 二分搜尋第一個 ≥ target 的位置（lower bound）
// 時間複雜度: O(log n)，空間複雜度: O(1)
function searchInsert(nums, target) {
    let lo = 0, hi = nums.length;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        if (nums[mid] < target)
            lo = mid + 1;
        else
            hi = mid;
    }
    return lo;
}

