#include <vector>
using namespace std;

class Solution {
public:
    /**
     * 二分搜尋
     * 時間複雜度: O(log n)
     * 空間複雜度: O(1)
     */
    int searchInsert(vector<int>& nums, int target) {
        int left = 0;
        int right = nums.size() - 1;

        while (left <= right) {
            int mid = left + (right - left) / 2;

            if (nums[mid] == target) {
                return mid;
            } else if (nums[mid] < target) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return left;
    }
};

