// 二分搜尋第一個 ≥ target 的位置（lower bound）
// 時間複雜度: O(log n)，空間複雜度: O(1)
int searchInsert(int* nums, int numsSize, int target) {
    int lo = 0, hi = numsSize;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (nums[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}
